<script setup lang="ts">
import {useApp} from '../store';import {progress} from '@jp/core';import WeekChart from '../components/WeekChart.vue';const app=useApp();const names={new:'新词',learning:'学习中',review:'复习中',mastered:'已掌握'};const bookWords=(id:string)=>app.data.words.filter(w=>app.data.lessons.some(l=>l.id===w.lessonId&&l.bookId===id));
</script>
<template><section class="page-heading"><div><p class="eyebrow">YOUR LITTLE STEPS</p><h1>每一点积累，都算数。</h1><p class="muted">看看你已经走过的路。</p></div><span class="streak">连续学习 {{app.stats.streak}} 天</span></section><section class="metric-row"><div><span>累计学习</span><strong>{{app.stats.learned}}<small>词</small></strong></div><div><span>累计评价</span><strong>{{app.stats.totalReviews}}<small>次</small></strong></div><div><span>当前待复习</span><strong>{{app.stats.due}}<small>词</small></strong></div><div><span>整体进度</span><strong>{{app.stats.percent}}<small>%</small></strong></div></section><div class="home-columns stats-columns"><section><h2>最近 7 天学习量</h2><p class="muted">每次学习与复习评价记为一次</p><WeekChart :days="app.stats.days"/></section><section><h2>记忆的不同阶段</h2><div v-for="(name,key) in names" :key="key" class="state-row"><span>{{name}}</span><div class="progress"><i :style="{width:(app.stats.counts[key]/Math.max(app.stats.total,1)*100)+'%'}"></i></div><strong>{{app.stats.counts[key]}}</strong></div><small class="muted">掌握：记忆稳定性达到 30 天，仍会安排复习。</small></section></div><section><h2>词书与课次进度</h2><div v-for="b in app.data.books" :key="b.id" class="stats-book"><div class="section-title"><RouterLink :to="'/books/'+b.id"><h3>{{b.title}}</h3></RouterLink><span>已学 {{progress(app.data,bookWords(b.id)).learned}} / {{progress(app.data,bookWords(b.id)).total}} 词</span></div><div v-for="l in app.data.lessons.filter(l=>l.bookId===b.id)" :key="l.id" class="state-row"><span>{{l.title}}</span><div class="progress"><i :style="{width:progress(app.data,app.data.words.filter(w=>w.lessonId===l.id)).percent+'%'}"></i></div><small>{{progress(app.data,app.data.words.filter(w=>w.lessonId===l.id)).percent}}%</small></div></div></section></template>
